use vstd::prelude::*;

verus! {

/// Splits a vector `a` into two parts at index `mid = a.len() / 2`.
/// - If `a.len() == 0`, returns (`[]`, `[]`).
/// - If `a.len() == 1`, returns (`[]`, `[x]`).
/// - In general, for `n = a.len()`, the first part has length `n/2`
///   and the second part has length `n - n/2`.
fn array_split(a: Vec<i32>) -> (first: Vec<i32>, second: Vec<i32>)
    ensures
        // Let n = original length, mid = n/2.
        let n = a.len();
        let mid = n / 2;
        // The two returned parts have exactly these lengths.
        first.len() == mid,
        second.len() == n - mid,
        // And concatenating their contents reproduces the original.
        first.to_seq() + second.to_seq() == a.to_seq(),
{
    let mut first_part = a;
    let mid = first_part.len() / 2;
    let second_part = first_part.split_off(mid);
    // Naming the tuple elements to match our `ensures`.
    (first_part, second_part)
}

} // end of `verus!`


